sys_script.script:
(function executeRule(current, previous /* null when async */) {

    /* ==========================================
       ONLY WHEN CLAIM BECOMES APPROVED
    ========================================== */

    var status =
        (
            current.getValue(
                'u_claim_status'
            ) || ''
        )
        .toLowerCase();


    if (status !== 'approved') {
        return;
    }


    /* ==========================================
       GENERATE ONLY ONCE
    ========================================== */

    if (
        !current.getValue(
            'collection_token'
        )
    ) {

        current.setValue(
            'collection_token',
            gs.generateGUID()
        );

    }


    current.setValue(
        'handover_completed',
        false
    );

})(current, previous);
